package com.coffeeshop.repository;import com.coffeeshop.dto.PurchasingCommands;import com.coffeeshop.exception.DatabaseException;import com.coffeeshop.model.PurchasingModels;import javax.sql.DataSource;import java.math.*;import java.sql.*;import java.util.*;public final class JdbcPurchasingRepository implements PurchasingRepository{private final DataSource ds;public JdbcPurchasingRepository(DataSource d){ds=Objects.requireNonNull(d);}public PurchasingModels.Catalog load(){try(Connection c=ds.getConnection()){return new PurchasingModels.Catalog(suppliers(c),items(c),purchases(c));}catch(SQLException e){throw fail("Unable to load purchasing data.",e);}}private List<PurchasingModels.Supplier>suppliers(Connection c)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT supplier_id,supplier_code,supplier_name,contact_person,phone,email,address,notes,is_active,row_version FROM dbo.suppliers ORDER BY supplier_name");ResultSet r=s.executeQuery()){List<PurchasingModels.Supplier>x=new ArrayList<>();while(r.next())x.add(new PurchasingModels.Supplier(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getBoolean(9),r.getBytes(10)));return x;}}private List<PurchasingModels.Item>items(Connection c)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT i.inventory_item_id,i.item_code,i.item_name,u.unit_name,i.is_active FROM dbo.inventory_items i JOIN dbo.units_of_measure u ON u.unit_of_measure_id=i.unit_of_measure_id ORDER BY i.item_name");ResultSet r=s.executeQuery()){List<PurchasingModels.Item>x=new ArrayList<>();while(r.next())x.add(new PurchasingModels.Item(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getBoolean(5)));return x;}}private List<PurchasingModels.Purchase>purchases(Connection c)throws SQLException{String q="SELECT p.purchase_id,p.purchase_number,p.supplier_id,s.supplier_name,p.purchased_at,p.status,p.subtotal_amount,p.discount_amount,p.tax_amount,p.total_amount,p.supplier_invoice_number,p.notes,p.row_version FROM dbo.purchases p JOIN dbo.suppliers s ON s.supplier_id=p.supplier_id ORDER BY p.purchased_at DESC,p.purchase_id DESC";List<PurchasingModels.Purchase>x=new ArrayList<>();try(PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){while(r.next())x.add(new PurchasingModels.Purchase(r.getLong(1),r.getString(2),r.getLong(3),r.getString(4),r.getTimestamp(5).toLocalDateTime(),r.getString(6),r.getBigDecimal(7),r.getBigDecimal(8),r.getBigDecimal(9),r.getBigDecimal(10),r.getString(11),r.getString(12),r.getBytes(13),purchaseItems(c,r.getLong(1))));}return x;}private List<PurchasingModels.PurchaseItem>purchaseItems(Connection c,long id)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT pi.purchase_item_id,pi.inventory_item_id,i.item_name,u.unit_name,pi.quantity,pi.unit_cost,pi.line_total,pi.row_version FROM dbo.purchase_items pi JOIN dbo.inventory_items i ON i.inventory_item_id=pi.inventory_item_id JOIN dbo.units_of_measure u ON u.unit_of_measure_id=i.unit_of_measure_id WHERE pi.purchase_id=? ORDER BY i.item_name")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){List<PurchasingModels.PurchaseItem>x=new ArrayList<>();while(r.next())x.add(new PurchasingModels.PurchaseItem(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getBigDecimal(5),r.getBigDecimal(6),r.getBigDecimal(7),r.getBytes(8)));return x;}}}public long saveSupplier(PurchasingCommands.Supplier q){String sql=q.id()==null?"INSERT dbo.suppliers(supplier_code,supplier_name,contact_person,phone,email,address,notes,is_active) VALUES(?,?,?,?,?,?,?,?)":"UPDATE dbo.suppliers SET supplier_code=?,supplier_name=?,contact_person=?,phone=?,email=?,address=?,notes=?,is_active=?,updated_at=SYSUTCDATETIME() WHERE supplier_id=? AND row_version=?";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){s.setString(1,q.code());s.setString(2,q.name());nullable(s,3,q.contact());nullable(s,4,q.phone());nullable(s,5,q.email());nullable(s,6,q.address());nullable(s,7,q.notes());s.setBoolean(8,q.active());if(q.id()!=null){s.setLong(9,q.id());s.setBytes(10,q.version());one(s.executeUpdate());return q.id();}s.executeUpdate();return key(s);}catch(SQLException e){throw fail("Unable to save supplier. Check that its code is unique.",e);}}public void setSupplierActive(long id,boolean active,byte[]v){try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement("UPDATE dbo.suppliers SET is_active=?,updated_at=SYSUTCDATETIME() WHERE supplier_id=? AND row_version=?")){s.setBoolean(1,active);s.setLong(2,id);s.setBytes(3,v);one(s.executeUpdate());}catch(SQLException e){throw fail("Unable to update supplier.",e);}}public long saveDraft(PurchasingCommands.Purchase q,long user){try(Connection c=ds.getConnection()){c.setAutoCommit(false);try{BigDecimal subtotal=q.items().stream().map(x->x.quantity().multiply(x.unitCost()).setScale(4,RoundingMode.HALF_UP)).reduce(BigDecimal.ZERO,BigDecimal::add),total=subtotal.subtract(q.discount()).add(q.tax());long id;if(q.id()==null){try(PreparedStatement s=c.prepareStatement("INSERT dbo.purchases(supplier_id,purchase_number,purchased_at,subtotal_amount,discount_amount,tax_amount,total_amount,supplier_invoice_number,notes,created_by_user_id) VALUES(?,CONCAT((SELECT COALESCE(MAX(CASE WHEN setting_key='numbering.purchase.prefix' THEN setting_value END),'PUR') FROM dbo.settings),FORMAT(NEXT VALUE FOR dbo.seq_purchase_number,'00000000')),?,?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){header(s,q,subtotal,total);s.setLong(9,user);s.executeUpdate();id=key(s);}}else{id=q.id();try(PreparedStatement s=c.prepareStatement("UPDATE dbo.purchases SET supplier_id=?,purchased_at=?,subtotal_amount=?,discount_amount=?,tax_amount=?,total_amount=?,supplier_invoice_number=?,notes=?,updated_at=SYSUTCDATETIME() WHERE purchase_id=? AND status='DRAFT' AND row_version=?")){header(s,q,subtotal,total);s.setLong(9,id);s.setBytes(10,q.version());one(s.executeUpdate());}try(PreparedStatement s=c.prepareStatement("DELETE FROM dbo.purchase_items WHERE purchase_id=?")){s.setLong(1,id);s.executeUpdate();}}try(PreparedStatement s=c.prepareStatement("INSERT dbo.purchase_items(purchase_id,inventory_item_id,quantity,unit_cost,line_total) VALUES(?,?,?,?,?)")){for(PurchasingCommands.Line l:q.items()){s.setLong(1,id);s.setLong(2,l.itemId());s.setBigDecimal(3,l.quantity());s.setBigDecimal(4,l.unitCost());s.setBigDecimal(5,l.quantity().multiply(l.unitCost()).setScale(4,RoundingMode.HALF_UP));s.addBatch();}s.executeBatch();}c.commit();return id;}catch(Exception e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){throw fail("Unable to save purchase.",e);}}public void receive(long id,long user,byte[]v){try(Connection c=ds.getConnection()){c.setAutoCommit(false);c.setTransactionIsolation(Connection.TRANSACTION_SERIALIZABLE);try{try(PreparedStatement s=c.prepareStatement("UPDATE dbo.purchases SET status='RECEIVED',updated_at=SYSUTCDATETIME() WHERE purchase_id=? AND status='DRAFT' AND row_version=?")){s.setLong(1,id);s.setBytes(2,v);one(s.executeUpdate());}try(PreparedStatement s=c.prepareStatement("SELECT inventory_item_id,quantity FROM dbo.purchase_items WHERE purchase_id=?")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){while(r.next()){long item=r.getLong(1);BigDecimal qty=r.getBigDecimal(2);try(PreparedStatement u=c.prepareStatement("UPDATE dbo.inventory_items SET current_stock_quantity=current_stock_quantity+?,updated_at=SYSUTCDATETIME() WHERE inventory_item_id=?")){u.setBigDecimal(1,qty);u.setLong(2,item);one(u.executeUpdate());}try(PreparedStatement m=c.prepareStatement("INSERT dbo.inventory_movements(inventory_item_id,purchase_id,recorded_by_user_id,movement_type,quantity_delta,reason) VALUES(?,?,?,'PURCHASE',?,'Purchase received')")){m.setLong(1,item);m.setLong(2,id);m.setLong(3,user);m.setBigDecimal(4,qty);m.executeUpdate();}}}}c.commit();}catch(Exception e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){throw fail("Unable to receive purchase.",e);}}public void cancel(long id,byte[]v){try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement("UPDATE dbo.purchases SET status='CANCELLED',updated_at=SYSUTCDATETIME() WHERE purchase_id=? AND status='DRAFT' AND row_version=?")){s.setLong(1,id);s.setBytes(2,v);one(s.executeUpdate());}catch(SQLException e){throw fail("Unable to cancel purchase.",e);}}private static void header(PreparedStatement s,PurchasingCommands.Purchase q,BigDecimal subtotal,BigDecimal total)throws SQLException{s.setLong(1,q.supplierId());s.setTimestamp(2,Timestamp.valueOf(q.purchasedAt()));s.setBigDecimal(3,subtotal);s.setBigDecimal(4,q.discount());s.setBigDecimal(5,q.tax());s.setBigDecimal(6,total);nullable(s,7,q.invoice());nullable(s,8,q.notes());}private static void nullable(PreparedStatement s,int i,String v)throws SQLException{if(v==null)s.setNull(i,Types.NVARCHAR);else s.setString(i,v);}private static void one(int n){if(n!=1)throw new IllegalStateException("Record changed or is no longer editable. Refresh and try again.");}private static long key(PreparedStatement s)throws SQLException{try(ResultSet r=s.getGeneratedKeys()){if(!r.next())throw new SQLException("Generated key unavailable");return r.getLong(1);}}private static DatabaseException fail(String m,Exception e){return new DatabaseException(m,e);}}
